    forkSandbox: {
        parameters: {
            query?: never;
            header: {
                /** @description Idempotency-Key header. Required on create. The same key and body return the original sandbox. A timed-out create is recovered on retry. */
                "idempotency-key": string;
                /** @description The most this start may cost in burst fees, in millionths of a US dollar: 0 refuses any fee. A start that would cost more is refused with 429 burst_fee_too_high, which says when it would cost nothing. Left out, it pays what the account's monthly budget allows. See GET /v1/burst. */
                "agental-max-burst-fee"?: string;
            };
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    name: string;
                    /** @description true: the fork goes on from where the source was, with every process that ran in it running on and what they held in memory, instead of starting from a copy of its disk. It has its own address, machine id, SSH host key and random seed, and its processes still hold the source's environment, its token among them, until they end. A running source is paused while its memory is written, about a second for every 2 to 3 GiB; a source stopped with keepMemory gives the memory it kept and stays as it was. Only on sandboxes whose host offers it (501 driver_operation_unavailable elsewhere); a stopped source that kept no memory is 409 invalid_state. */
                    memory?: boolean;
                };
            };
        };
        responses: {
            /** @description Idempotent replay of a finished fork. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Sandbox"];
                };
            };
            /** @description Fork created and running: a new sandbox of the same size with a copy of what the source held, on the source's template, with the source's own secrets and addresses. It is held to that template's outbound rule as it is now, with those addresses on top, from its first boot. The source is left as it was. With memory, the fork's processes are the source's, running on. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Sandbox"];
                };
            };
            /** @description Fork was accepted but the host result is uncertain. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["AcceptedCreate"];
                };
            };
            /** @description Missing or invalid API key. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description billing_required: the account is on the free plan with no card saved. out_of_credit: its credits, the plan's and the top-ups, are used. size_not_on_plan: the plan does not make sandboxes of the source's size, and the message names the plan that does. Nothing was forked. */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Not found. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Capacity, name, or idempotency conflict. too_many_addresses: the template's rule and the source's own addresses come to more than 100. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description This idempotency key already failed. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description running_limit_reached: the account runs as many sandboxes as its plan's runningUnits allows. burst_fee_too_high: the start would cost more in burst fees than the Agental-Max-Burst-Fee header allows. burst_budget_reached: the burst fee would take this month's fees past the account's budget. feeMicros says what the start would have cost; retryAfterSeconds and the Retry-After header say when it would cost nothing. Nothing was forked. */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The compute host rejected the fork. */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Forks are not offered here. network_policy_unavailable: the template holds the fork to blocked or an allowlist where GET /v1/policy says networkPolicy is false. */
            501: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
