        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description base64url of the SHA-256 of a secret only the command holds (PKCE, S256). */
                    codeChallenge: string;
                    /**
                     * @description Where the browser brings the code back to: http on the command's own computer, at 127.0.0.1, [::1] or localhost, with a port.
                     * @example http://127.0.0.1:53682/callback
                     */
                    redirectUri: string;
                    /** @description Given back to the redirectUri with the code, so the command knows the answer is to this request. */
                    state: string;
                    computer: string;
                    /** @description The invite code, given in the terminal. While sign-up is invite-only a wrong one is refused here, before any browser is opened. */
                    inviteCode?: string;
                    /** @description The organization to make the command's key in, as agental org use asks: the page offers it first. Left out, the one the person acts in on the site. A key acts in its organization for good. */
                    organizationId?: string;
                };
            };
        };
